using System;using System.Drawing;using System.Windows.Forms;using System.Runtime.InteropServices;using System.Threading;using System.Web.Script.Serialization;using System.Collections.Generic;
class HitFixture : Form {
 [StructLayout(LayoutKind.Sequential)]struct Point{public int X,Y;}
 [DllImport("user32.dll")]static extern bool SetProcessDpiAwarenessContext(IntPtr c);
 [DllImport("user32.dll")]static extern bool SetCursorPos(int x,int y);
 [DllImport("user32.dll")]static extern IntPtr WindowFromPoint(Point p);
 [DllImport("user32.dll")]static extern uint GetWindowThreadProcessId(IntPtr h,out uint pid);
 [DllImport("user32.dll")]static extern void mouse_event(uint flags,uint dx,uint dy,uint data,UIntPtr extra);
 int clicks;bool pressed;static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
 protected override bool ShowWithoutActivation{get{return true;}}

 [STAThread]static void Main(string[] args){SetProcessDpiAwarenessContext(new IntPtr(-4));var form=new HitFixture{StartPosition=FormStartPosition.Manual,FormBorderStyle=FormBorderStyle.None,TopMost=true,ShowInTaskbar=false,AutoScaleMode=AutoScaleMode.None,BackColor=Color.Teal,Bounds=new Rectangle(Int32.Parse(args[0]),Int32.Parse(args[1]),Int32.Parse(args[2]),Int32.Parse(args[3]))};form.MouseDown+=(s,e)=>Interlocked.Increment(ref form.clicks);form.Shown+=(s,e)=>{Console.WriteLine("{\"ready\":true}");Console.Out.Flush();var thread=new Thread(()=>{string line;while((line=Console.ReadLine())!=null){try{var cmd=Json.Deserialize<Dictionary<string,object>>(line);if(Convert.ToString(cmd["action"])=="close"){if(form.pressed)mouse_event(4,0,0,0,UIntPtr.Zero);form.BeginInvoke(new Action(()=>form.Close()));return;}int x=Convert.ToInt32(cmd["x"]),y=Convert.ToInt32(cmd["y"]);SetCursorPos(x,y);uint pid;GetWindowThreadProcessId(WindowFromPoint(new Point{X=x,Y=y}),out pid);bool allowed=pid==(uint)System.Diagnostics.Process.GetCurrentProcess().Id;foreach(object item in (System.Collections.IEnumerable)cmd["allowed"])if(pid==Convert.ToUInt32(item))allowed=true;if(!allowed)throw new Exception("Point is covered by an unrelated window (pid "+pid+"); no click was sent");int before=form.clicks;string action=Convert.ToString(cmd["action"]);if(action=="down"||action=="click"){mouse_event(2,0,0,0,UIntPtr.Zero);form.pressed=true;}if(action=="up"||action=="click"){mouse_event(4,0,0,0,UIntPtr.Zero);form.pressed=false;}Thread.Sleep(250);Console.WriteLine(Json.Serialize(new{before=before,after=form.clicks,pid=pid}));Console.Out.Flush();}catch(Exception error){if(form.pressed){mouse_event(4,0,0,0,UIntPtr.Zero);form.pressed=false;}Console.WriteLine(Json.Serialize(new{error=error.Message}));Console.Out.Flush();}}form.BeginInvoke(new Action(()=>form.Close()));});thread.IsBackground=true;thread.Start();};Application.Run(form);}
}
